import type { GlossaryEntry } from '../types/dictionary';

type PartOfSpeech = GlossaryEntry['partOfSpeech'];

function entry(headword: string, partOfSpeech: PartOfSpeech, kidDefinition: string, example: string, forms = ''): GlossaryEntry {
  const list = forms.split(' ').filter((f) => f.length > 0);
  return list.length > 0 ? { headword, partOfSpeech, kidDefinition, example, forms: list } : { headword, partOfSpeech, kidDefinition, example };
}

